Definition pre_flush_chk (j : Z) : bool :=
  (rflat_chk (kn_X (xk_T j)) x_regions &&
   match xchain RSEGS x_regions XNV PRE_F1 (xs0 (xk_T j)) with
   | Some s1 =>
       Z.eqb (xs_pc s1) 0x16b42c &&
       match stdio_call XNV (xs_sr s1) (xs_kn s1) with
       | Some r =>
           Z.eqb (sc_fd r) 1 && expr_lit_eqb (sc_wb r) ASTDOUT_BUF && expr_lit_eqb (sc_wp r) (ASTDOUT_BUF + 2 * j)
           && expr_lit_eqb (sc_s r) 0 && expr_lit_eqb (sc_l r) 0 && sp_off_chk (sc_sp r)
           && rflat_chk (sc_kn r) x_regions
           && xchain_rebase RSEGS x_regions XNV2 XNVT PRE_F2 (XS (sc_ret r) (sc_sr r) (sc_kn r)) ACUT XKEPT sr_T kn_T
       | None => false
       end
   | None => false
   end)%bool.

Lemma x_regions_buf : forall E (i : Z), (0 <= i < 1024)%Z ->
  (ASP_LO <= bv_unsigned (ev E 0))%Z -> (bv_unsigned (ev E 0) <= ASP_HI)%Z ->
  (bv_unsigned (ev E 40) + 0x14dc00 + 96 <= AIMGR_LO \/ AIMGR_LO + AIMGR_N <= bv_unsigned (ev E 40) + 0x14dc00)%Z ->
  (bv_unsigned (ev E 40) + 0x224ac0 + 96 <= AIMGR_LO \/ AIMGR_LO + AIMGR_N <= bv_unsigned (ev E 40) + 0x224ac0)%Z ->
  outside (Z_to_bv 64 (ASTDOUT_BUF + i)) (map (rdenot E) x_regions).
