Section Flush.
  Context {fx : DFP}.
  Variable j : Z.
  Hypothesis Hj : (1 <= j <= 3)%Z.
  Hypothesis CHK : pre_flush_chk j = true.

  Theorem ax_flush : forall vals R M msF mo L S Zr (pending : list byte),
    length vals = XNV ->
    regs_ok (XENV vals) x_sr R -> know_ok RSEGS (XENV vals) M (kn_X (xk_T j)) ->
    length pending = Z.to_nat (2 * j) ->
    rdn RSEGS M (Z_to_bv 64 ASTDOUT_BUF) (length pending) = Some pending ->
    fd_lookup (m_fds mo) (Z_to_bv 64 1) = Some (FdChannel (Z_to_bv 64 1)) ->
    lzok RSEGS L S Zr (mkCfg msF mo) -> restrict L S msF = mkst R (Z_to_bv 64 AEXIT) M (seg_rom RSEGS) ->
    realizes RSEGS (mkCfg msF mo)
      (t_emit (map (WriteEv (Z_to_bv 64 1)) pending) (t_exit (bv_and (vals_ev vals 2) (Z_to_bv 64 255)) (m_fs mo))).
Proof.
